INSERT INTO events (id, name, kind, time_mode, at_confidence, start_confidence, end_confidence, date_note, at_year, at_month, at_day, at_abs, start_year, start_month, start_day, start_abs, end_year, end_month, end_day, end_abs, summary, meaning, content, location_id) VALUES ('mongol-campaign-jin', '蒙古攻金', 'battle', 'span', NULL, 'year', 'year', NULL, NULL, NULL, NULL, NULL, 1211, 1, NULL, 14532, 1234, 1, NULL, 14808, '成吉思汗至窝阔台时期对金朝发动长期战争，1234年蔡州陷落，金亡。', NULL, NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, at_confidence, start_confidence, end_confidence, date_note, at_year, at_month, at_day, at_abs, start_year, start_month, start_day, start_abs, end_year, end_month, end_day, end_abs, summary, meaning, content, location_id) VALUES ('mongol-west-campaign', '西征花剌子模', 'battle', 'span', NULL, 'approximate_year', 'approximate_year', '1219–1225年，史料月日不一；原不确定范围：1219年1月至1225年1月；按既有事件说明转为持续区间。', NULL, NULL, NULL, NULL, 1219, 1, NULL, 14628, 1225, 1, NULL, 14700, '成吉思汗率军西征花剌子模，兵锋远达中亚，奠定蒙古西征格局。', NULL, NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, at_confidence, start_confidence, end_confidence, date_note, at_year, at_month, at_day, at_abs, start_year, start_month, start_day, start_abs, end_year, end_month, end_day, end_abs, summary, meaning, content, location_id) VALUES ('tolui-regency', '拖雷监国', 'politics', 'span', NULL, 'approximate_year', 'approximate_year', '1227–1229年，库里尔台推举窝阔台前；原不确定范围：1227年1月至1229年1月；按既有事件说明转为持续区间。', NULL, NULL, NULL, NULL, 1227, 1, NULL, 14724, 1229, 1, NULL, 14748, '成吉思汗去世后幼子拖雷监国，两年后库里尔台推举窝阔台继位。', NULL, NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, at_confidence, start_confidence, end_confidence, date_note, at_year, at_month, at_day, at_abs, start_year, start_month, start_day, start_abs, end_year, end_month, end_day, end_abs, summary, meaning, content, location_id) VALUES ('mongke-death', '蒙哥汗驾崩', 'politics', 'point', 'year', NULL, NULL, '1259年攻宋四川军中', 1259, 12, NULL, 15119, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '蒙哥汗攻宋途中于四川去世，忽必烈与阿里不哥随即展开汗位之争。', NULL, NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, at_confidence, start_confidence, end_confidence, date_note, at_year, at_month, at_day, at_abs, start_year, start_month, start_day, start_abs, end_year, end_month, end_day, end_abs, summary, meaning, content, location_id) VALUES ('great-khan-contention', '忽必烈与阿里不哥争位', 'politics', 'span', NULL, 'year', 'year', NULL, NULL, NULL, NULL, NULL, 1260, 1, NULL, 15120, 1264, 1, NULL, 15168, '蒙哥死后忽必烈与阿里不哥各举忽里台互不承认，1264年忽必烈获胜，帝国走向分裂。', NULL, NULL, NULL)
INSERT INTO events (id, name, kind, time_mode, at_confidence, start_confidence, end_confidence, date_note, at_year, at_month, at_day, at_abs, start_year, start_month, start_day, start_abs, end_year, end_month, end_day, end_abs, summary, meaning, content, location_id) VALUES ('mongol-campaign-song', '蒙古攻宋', 'battle', 'span', NULL, 'year', 'year', NULL, NULL, NULL, NULL, NULL, 1235, 1, NULL, 14820, 1279, 1, NULL, 15348, '蒙古自窝阔台时期起持续南征；忽必烈于1271年定国号大元后战争仍继续，经襄樊之战、崖山海战，1279年灭南宋。', NULL, NULL, NULL)
