-- EraLens period import: mongol-pre-yuan
-- Window: 1206-01 .. 1271-12
BEGIN;

-- cleanup
-- remove stale auto-generated 史料缺 (regency gaps are intentional blanks)
DELETE FROM reigns WHERE dynasty_id IN ('mongol-empire') AND person_id = 'system-missing-ruler';

-- persons
VALUES ('temujin', '铁木真', ARRAY[]::text[], NULL, NULL, 1162, NULL, NULL, 'month', 1227, NULL, NULL, 'month', ARRAY['大汗'], '铁木真，孛儿只斤氏，后世称成吉思汗。经过多年征战与结盟统一蒙古高原诸部，1206年在忽里勒台被推举为大汗并建立大蒙古国；此后发动对金、西夏等地的战争，1227年在征夏途中去世。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/成吉思汗"}]'::jsonb, '法天启运圣武皇帝', '太祖', '成吉思汗')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, birth_day = EXCLUDED.birth_day, birth_confidence = EXCLUDED.birth_confidence, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, death_day = EXCLUDED.death_day, death_confidence = EXCLUDED.death_confidence, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
VALUES ('ogedei', '窝阔台', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['大汗'], '窝阔台，成吉思汗第三子，1229年经忽里勒台推举为大汗。其朝继续西征并于1234年灭金，扩展蒙古在中原和中亚的统治；任用耶律楚材治理华北，营建哈剌和林，去世后由皇后脱列哥那摄政。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/窝阔台"}]'::jsonb, '英文皇帝', '太宗', '窝阔台汗')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, birth_day = EXCLUDED.birth_day, birth_confidence = EXCLUDED.birth_confidence, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, death_day = EXCLUDED.death_day, death_confidence = EXCLUDED.death_confidence, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
VALUES ('guyuk', '贵由', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['大汗'], '贵由，窝阔台长子，1246年经忽里勒台即大汗位。其在位时间短，曾试图加强大汗对诸王和军队的控制，并与拔都关系紧张；1248年西行途中去世，之后皇后斡兀立海迷失摄政。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/贵由"}]'::jsonb, '钦定皇帝', '定宗', '贵由汗')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, birth_day = EXCLUDED.birth_day, birth_confidence = EXCLUDED.birth_confidence, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, death_day = EXCLUDED.death_day, death_confidence = EXCLUDED.death_confidence, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
VALUES ('mongke', '蒙哥', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['大汗'], '蒙哥，拖雷长子，1251年经忽里勒台推举为大汗。即位后整顿财政与人口登记，并派旭烈兀西征、命忽必烈经略南方；1259年攻宋期间在钓鱼城下去世，随后忽必烈与阿里不哥争位，帝国统合受到冲击。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/蒙哥"}]'::jsonb, '桓肃皇帝', '宪宗', '蒙哥汗')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, birth_day = EXCLUDED.birth_day, birth_confidence = EXCLUDED.birth_confidence, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, death_day = EXCLUDED.death_day, death_confidence = EXCLUDED.death_confidence, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
VALUES ('hu-bilie', '忽必烈', ARRAY[]::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, ARRAY['大汗','皇帝'], '忽必烈，成吉思汗之孙、拖雷之子。1260年即大汗位后与阿里不哥争位，1264年获胜；1271年定国号大元，1279年灭南宋，建都大都并确立中原王朝的行政制度。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/忽必烈"}]'::jsonb, NULL, NULL, '元世祖')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, alt_names = EXCLUDED.alt_names, ancestral_xing = EXCLUDED.ancestral_xing, clan_shi = EXCLUDED.clan_shi, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, birth_day = EXCLUDED.birth_day, birth_confidence = EXCLUDED.birth_confidence, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, death_day = EXCLUDED.death_day, death_confidence = EXCLUDED.death_confidence, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links, posthumous_name = EXCLUDED.posthumous_name, temple_name = EXCLUDED.temple_name, title = EXCLUDED.title;
